-- ============================================================================
-- تعبئة دليل الخدمات بشركات حقيقية (من مواقعها الرسمية ومصادر موثوقة).
-- تُدرج مفعّلة وغير «موثّقة الرخصة» — وثّقي الرخصة من صفحة الإدارة بعد التحقق.
-- آمن لو أُعيد تشغيله: لا يكرّر شركة موجودة بنفس القسم والإمارة والاسم.
-- يُنفَّذ بعد service_providers.sql و service_categories_v2.sql من Supabase → SQL Editor.
-- ============================================================================
-- تعطيل مؤقت لحماية الإغراق أثناء الإدراج الجماعي من SQL Editor (تُعاد في آخر الملف)
do $$ begin
  if exists (select 1 from pg_trigger where tgname = 'aq_rate_limit_service_providers') then
    alter table public.service_providers disable trigger aq_rate_limit_service_providers;
  end if;
end $$;
alter table public.service_providers add column if not exists founded_year int;
alter table public.service_providers add column if not exists source_url text;
alter table public.service_providers add column if not exists about text;
alter table public.service_providers add column if not exists address text;
alter table public.service_providers add column if not exists map_url text;
alter table public.service_providers add column if not exists portfolio text[] not null default '{}';
alter table public.service_providers add column if not exists team_info text;

