select 'contracting', 'Bond Interiors', 'Bond Interiors', 'دبي', 'مدينة دبي الصناعية', '+97145667720', 'https://bondinteriors.com', 1986, 'شركة مقاولات تشطيبات داخلية فاخرة وتصنيع في دبي منذ 1986.', 'https://bondinteriors.com/about-us/', 'بدأت بوند إنتيريرز عام 1986 كشركة صيانة ثم أصبحت من شركات مقاولات التشطيبات الداخلية الراقية والتصنيع. تجمع عمليات الإنتاج في منشأة بمساحة 550 ألف قدم مربعة، وتقدم أعمال النجارة والمعادن والزجاج والرخام والأعمال الكهروميكانيكية والمدنية.', 'https://bondinteriors.com/wp-content/uploads/2023/09/Bond-Interiors-Logo.png', 'info@bondinteriors.com', 'سيح شعيب 3، مدينة دبي الصناعية، دبي، ص.ب 15758', null, array['تشطيبات لعلامات مثل هيرميس وفيرساتشي وجورجيو أرماني', 'فلل دبي هيلز استيت', 'فلل داماك هيلز', 'أعمال النجارة والتصنيع', 'المطاعم والمقاهي والتجزئة']::text[], 'شركة عائلية أسسها ويديرها سعد مواسس.', true
where not exists (select 1 from public.service_providers where category = 'contracting' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Bond Interiors'));
