select 'contracting', 'Al Taameer Group', 'Al Taameer Group', 'رأس الخيمة', null, '+97172222988', 'https://www.altaameergroup.com', 1997, 'مجموعة مقاولات مباني وأعمال مدنية في رأس الخيمة مصنفة درجة أولى، تأسست 1997.', 'https://www.altaameergroup.com/', 'تأسست مجموعة التعمير عام 1997 وتعمل مقاولًا رئيسيًا لأعمال المباني والأعمال المدنية في القطاعين العام والخاص، وتذكر أنها مصنفة درجة أولى. كوّنت مجموعة شركات عام 2003 تشمل الإنشاءات والأخشاب والديكور والتصميم الداخلي والألمنيوم والزجاج.', 'https://www.altaameergroup.com/frontend/images/ALTAAMEER.png', 'altaameer@altaameergroup.com', 'مبنى التعمير، شارع المنتصر، بالقرب من راك مول، رأس الخيمة', null, array['التعمير للإنشاءات', 'التعمير للأخشاب والديكور', 'آي فيجر للتصميم الداخلي', 'التعمير للألمنيوم والزجاج', '45 مشروعًا رئيسيًا منجزًا']::text[], 'الرئيس التنفيذي عبدالله حسن محمد حميدان الزعابي.', true
where not exists (select 1 from public.service_providers where category = 'contracting' and emirate = 'رأس الخيمة' and lower(coalesce(name_en, name_ar)) = lower('Al Taameer Group'));
