select 'residency', 'Arnifi Corporate Service Providers L.L.C', 'Arnifi Corporate Service Providers L.L.C', 'دبي', 'البرشاء الأولى', '+971585054423', 'https://arnifi.com', null, 'منصة لتأسيس الشركات وخدمات التأشيرات والمحاسبة مقرها في دبي.', 'https://arnifi.com/', 'تقدّم أرنيفي نفسها منصة مدعومة بالذكاء الاصطناعي لتأسيس الشركات وتشغيلها عالمياً، وتذكر أنها تخدم أكثر من 750 شركة. تشمل خدماتها تأسيس الشركات والامتثال بعد التأسيس والتصديقات والتأشيرات والمحاسبة والخدمات المصرفية. لها مكتب في دبي وآخر في بنغالورو بالهند.', 'https://arnifi-be-prod-assets.s3.ap-south-1.amazonaws.com/Arnifi_Primary_Logo_Blue_8fc3f7c3_80d1da9412_13b9fa5871.png', 'hello@arnifi.com', 'مكتب 1105، برج API Trio، شارع الشيخ زايد، البرشاء الأولى، دبي', null, array['تأسيس الشركات', 'خدمات التأشيرات', 'المحاسبة ومسك الدفاتر', 'الخدمات القانونية', 'فتح الحسابات المصرفية']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'residency' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Arnifi Corporate Service Providers L.L.C'));
