select 'residency', 'Emirabiz', 'Emirabiz', 'دبي', 'إكسبو سيتي دبي', '+97145531391', 'https://emirabiz.com', null, 'استشارات تأسيس أعمال وخدمات شركات في إكسبو سيتي دبي، تشمل الإقامة والإقامة الذهبية.', 'https://emirabiz.com/contacts/', 'إميرابيز شركة استشارات لتأسيس الأعمال وخدمات الشركات مقرها إكسبو سيتي دبي، وتذكر أنها تعمل في الإمارات منذ 2013. تقدم تأسيس الشركات في البر الرئيسي والمناطق الحرة والأوفشور، وخدمات الإقامة والإقامة الذهبية والمحاسبة والضرائب. تعمل باللغتين الإنجليزية والروسية.', 'https://emirabiz.com/images/logo.svg', 'hello@emirabiz.com', 'الطابق الأول، مبنى مانغروف 6، منطقة الاستدامة، إكسبو سيتي دبي، دبي', 'https://www.google.ae/maps/place/24.959657964848862,55.152094303791635', array['تأسيس الشركات في دبي والمناطق الحرة', 'الإقامة الذهبية', 'تأشيرة العمل الحر والإقامة العائلية', 'المحاسبة والضرائب', 'فتح الحسابات المصرفية']::text[], 'فريق داخلي من 25 متخصصاً في المحاسبة والضرائب والامتثال وتأسيس الأعمال.', true
where not exists (select 1 from public.service_providers where category = 'residency' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Emirabiz'));
